CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leads(id TEXT PRIMARY KEY,name TEXT NOT NULL,company TEXT NOT NULL,whatsapp TEXT NOT NULL,email TEXT NOT NULL,product_interest TEXT,source TEXT NOT NULL DEFAULT 'website',landing_page TEXT,visited_pages TEXT,consent_at TEXT NOT NULL,verified_at TEXT,status TEXT NOT NULL DEFAULT 'New',score INTEGER NOT NULL DEFAULT 0,tier TEXT NOT NULL DEFAULT 'COLD',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_leads_status_score ON leads(status,score DESC);
CREATE TABLE IF NOT EXISTS lead_events(id TEXT PRIMARY KEY,lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,event_type TEXT NOT NULL,score_delta INTEGER NOT NULL DEFAULT 0,metadata TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rfqs(id TEXT PRIMARY KEY,lead_id TEXT REFERENCES leads(id),company TEXT NOT NULL,whatsapp TEXT NOT NULL,email TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Draft',notes TEXT,verified_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rfq_items(id TEXT PRIMARY KEY,rfq_id TEXT NOT NULL REFERENCES rfqs(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),qty INTEGER NOT NULL CHECK(qty>0));
CREATE TABLE IF NOT EXISTS rfq_history(id TEXT PRIMARY KEY,rfq_id TEXT NOT NULL REFERENCES rfqs(id) ON DELETE CASCADE,from_status TEXT,to_status TEXT,note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers(id TEXT PRIMARY KEY,name TEXT NOT NULL,country TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,product_id TEXT REFERENCES products(id),supplier_id TEXT REFERENCES suppliers(id),type TEXT,status TEXT NOT NULL DEFAULT 'missing',r2_key TEXT,expires_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_sessions(id TEXT PRIMARY KEY,admin_user_id TEXT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY,admin_user_id TEXT,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,metadata TEXT,ip_address TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS otp_challenges(id TEXT PRIMARY KEY,email TEXT NOT NULL,code_hash TEXT NOT NULL,expires_at TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,consumed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
